#define EPSILON 0.0005
#define MIN_DISTANCE 0.005
#define MAX_DISTANCE 75. 
#define PRECISION 0.001
#define MAX_STEPS 110
#define BALL_RADIUS 3.2
#define SPOT_LIGHT_RADIUS 2.9
#define SHAPE_CYCLE 10.
#define BLINK_SPEED 3.
#define REPEAT_PATTERN 12.0
#define REPEAT_PATTERN_X 12.0
#define REPEAT_PATTERN_Y 12.0

#define TIME_SPEED_FACTOR 1.4
#define PI 3.1415926
#define SPOT_LIGHT_SPEED 0.6

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};



Material greyM() {
  vec3 aCol = vec3(0.7);
  vec3 dCol = vec3(0.7);
  vec3 sCol = vec3(0.7);
  float a = 55.;

  return Material(aCol, dCol, sCol, a);
}


Material grey;

// an array with various 'shapes' of a gyroid
const float ppTable[5] = float[5](
    2.0, 6.0, 3.0, 8., 10.
);


float sdSphere(vec3 pr, vec3 c, float r, mat3 tm) {
    vec3 p = pr * tm;
    float shapesCount = float(ppTable.length());
    int shape2 = int(mod(mod(iTime / SHAPE_CYCLE, shapesCount * SHAPE_CYCLE), shapesCount));
    int shape1 = int(mod((float(shape2 + 1)), shapesCount));
    float distSphere = abs(length(p - c) - r) - 0.3; // abs and (-0.09) at the end is to make a shell instead of a sphere 

    float gyroidDistance;
    float cycleTime = mod(iTime, SHAPE_CYCLE);
    vec3 pp1 = ppTable[shape1] * p; vec3 ve1 = pp1.xxz;
    vec3 pp2 = ppTable[shape2] * p; vec3 ve2 = pp1.yyx;


    if (cycleTime < BLINK_SPEED) {
         ve1 = mix(pp2.xxz, ve1, cycleTime / BLINK_SPEED);   
         ve2 = mix(pp2.yyx, ve2, cycleTime / BLINK_SPEED);   
    }


    gyroidDistance = abs(dot(sin(ve1), cos(ve2)) / 14.) - 0.03;
    return max(distSphere, gyroidDistance);
}

float scene(vec3 p) {
   // float reducedZ = (p.z - iTime * TIME_SPEED_FACTOR);
    float zi = mod(p.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN;
   // float zii = mod(p.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN;
    float xi = mod(p.x + 0.5 * REPEAT_PATTERN_X, REPEAT_PATTERN_X) - 0.5 * REPEAT_PATTERN_X;
    float yi = mod(p.y + 0.5 * REPEAT_PATTERN_Y, REPEAT_PATTERN_Y) - 0.5 * REPEAT_PATTERN_Y;
    //float mm = trunc((p.z - iTime * TIME_SPEED_FACTOR) / ((mod(p.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) + 1. * REPEAT_PATTERN )));
    //float zii = mod(reducedZ / zi);

  //  float mm = round(reducedZ / zi) * 2.;

    vec3 pr = vec3(xi , yi, zi);
    return sdSphere(pr, vec3(0., 0., 0.), BALL_RADIUS, rotateZ(iTime / 2.)); 
   //return sdSphere(pr, vec3(0., 0., 0.), BALL_RADIUS, rotateZ(iTime + cos(p.zi / 2.5 + 1. * cos(iTime)))); 
}



// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.02, -1.02) * EPSILON;
  return normalize(
    e.xyy * scene(p + e.xyy) +
    e.yyx * scene(p + e.yyx) +
    e.yxy * scene(p + e.yxy) +
    e.xxx * scene(p + e.xxx));
}


struct RaymarchRes {
    vec3 p; // surface hit point
    float d; // distance
};


RaymarchRes raymarch(vec3 ro, vec3 rd) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        float sf = scene(p); 
        t += sf;

        if (sf < PRECISION) { // we hit the surface at point p
            res.p = p;
            res.d = sf;
            break;
        } else if (sf > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            //t += sf.d; // we did not hit anything, keep on trying
    }

    res.d = t;
    return res;
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

float someShapingFunction() {
    float amplitude = 4.;
    float frequency = 1.;
    float x = iTime;
    float y = sin(x * frequency);
    float t = 0.01*(-iTime*130.0);
    y += sin(x*frequency*2.1 + t)*4.5;
    y += sin(x*frequency*1.72 + t*1.121)*4.0;
    y += sin(x*frequency*2.221 + t*0.437)*5.0;
    y += sin(x*frequency*3.1122+ t*4.269)*2.5;
    y *= amplitude*0.06;
    return y;
}


vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {
//   vec3 ro = vec3(2.1 + sin(iTime / 2.) * 3., 0. + cos(iTime / 3.) * 4., lookAt.z - 4. + sin(iTime) * 3.); 
   vec3 ro = vec3(2.1 + someShapingFunction(), 0. + someShapingFunction() * 1., lookAt.z - 4. + sin(iTime) * 3.); 
   return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    vec3 lightVector = vec3(0., 0., 0.);
    return lightVector;
}

vec3 wanderOnSphere(float time, float radius) {
    float azimuth = mod(time * SPOT_LIGHT_SPEED, 2.0 * PI); 
    float elevation = sin(time * SPOT_LIGHT_SPEED * 0.5) * PI * 2.5; 

    // change coordinates to cartesian system
    float x = radius * cos(elevation) * cos(azimuth);
    float y = radius * sin(elevation);
    float z = radius * cos(elevation) * sin(azimuth);// + iTime * TIME_SPEED_FACTOR ;

    return vec3(x, y, z);
}


vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 po = rr.p;

    //vec3 p = po;
    float zii = mod(po.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN;
    float xii = mod(po.x + 0.5 * REPEAT_PATTERN_X, REPEAT_PATTERN_X) - 0.5 * REPEAT_PATTERN_X;
    float yii = mod(po.y + 0.5 * REPEAT_PATTERN_Y, REPEAT_PATTERN_Y) - 0.5 * REPEAT_PATTERN_Y;


    vec3 normalToSurfaceVector = calcNormal(po);
    vec3 l = -normalize(-lo + po); // light direction
    Material m = grey;
    float zi = clamp((rr.p.z - iTime * TIME_SPEED_FACTOR + 4.) / REPEAT_PATTERN, 0., 1.); // we are making transition between materials - the further you are the more different color

    vec3 pii = vec3(xii, yii, zii);

    zi = exp(-zi*zi*zi*2.1);

    vec3 color = m.ambientColor; 
    /*
    vec3 diffusion = clamp(dot(l, normalToSurfaceVector), 0., 1.) * m.diffuseColor; // diffusion light
    float dotRV = clamp(dot(reflect(l, normalToSurfaceVector), rd), 0., 1.);
    vec3 specular =  clamp(pow(dotRV, m.alpha), 0., 1.) * m.specularColor; // specular light
    color += (specular + diffusion);
    */

    float light = clamp(dot(normalToSurfaceVector, l), 0., 5.);
    color *= vec3(light);

    /* 

    float y2 = sin(iTime * 2.);
    float y1 = 2.;//(sin(iTime) + 1.) / 2.;
    float ys = 0. + sin(iTime) / 2.;


    if (po.y < y1 + y2 && po.y > y2) {
        color = mix(spotLight1, color, smoothstep(y2, y1 + y2, po.y));
    } else if (po.y > y2 - y1 && po.y < y2) {
        color = mix(color, spotLight1, smoothstep(y2 - y1, y2, po.y));
    }
    */

    vec3 spotLight1 = vec3(1., 1, 1.);
    vec3 spotLight2 = vec3(1., 0., 0.);
    vec3 spotLight3 = vec3(1., 1., 0.);

    float dd = length(wanderOnSphere(iTime, BALL_RADIUS) - pii);
    color = +mix(color, color + spotLight1, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));
    dd = length(wanderOnSphere(iTime + 7., BALL_RADIUS) - pii);
    color = +mix(color, color + spotLight2, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));
    dd = length(wanderOnSphere(iTime + 9., BALL_RADIUS) - pii);
    color = +mix(color, color + spotLight3, smoothstep(0., SPOT_LIGHT_RADIUS, SPOT_LIGHT_RADIUS - dd));

    //dd = length(wanderOnSphere(iTime + 12., BALL_RADIUS)  - pii);
    //dd = length(pii);


    color *= zi;
    //color = vec3(dd / 10.);
    color = clamp(color, 0., 1.);


    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.5)); // vigniete

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    grey = greyM();

    vec3 lookAt = vec3(0.0,0.5, iTime * TIME_SPEED_FACTOR);
    vec3 ro = calculateCameraPosition(lookAt, uv);
    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -0.6)); // przy -6 fajne wzory
    vec3 lo = calculateLightPosition(lookAt);

//    vec4 backgroundColor = vec4(mix(vec3(0., 0.01, .1), vec3(0., 0., 0.), uv.y) * 1.8, 1.0);
    vec4 backgroundColor = vec4(0., 0., 0., 1.0);
    RaymarchRes rr = raymarch(ro, rd);

    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
}

mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
